+static const char *dec_type_to_name(unsigned int type)
+{
+	int i;
+	int size = ARRAY_SIZE(dec_type_name);
+
+	for (i = 0; i < size; i++) {
+		if (dec_type_name[i].codec_type == type)
+			return dec_type_name[i].name;
+	}
+
+	return "ERR";
+}
