+static const struct aml_video_fmt *aml_vdec_get_video_fmt(struct aml_vdec_dev
+							  *dev, u32 format)
+{
+	const struct aml_video_fmt *fmt;
+	unsigned int k;
+
+	for (k = 0; k < dev->pvdec_data->num_fmts; k++) {
+		fmt = &dev->pvdec_data->dec_fmt[k];
+		if (fmt->fourcc == format)
+			return fmt;
+	}
+
+	return NULL;
+}
